<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{api,type ApiResponse,type Review}from'@whaashop/shared';interface Page<T>{items:T[];total:number}const rows=ref<Review[]>([]),rating=ref(0),productId=ref<number>(),page=ref(1),size=ref(20),total=ref(0);async function load(){const{data}=await api.get<ApiResponse<Page<Review>>>('/admin/reviews',{params:{rating:rating.value,productId:productId.value,page:page.value,size:size.value}});rows.value=data.data.items;total.value=data.data.total}function search(){page.value=1;load()}async function visibility(r:Review){await api.patch(`/admin/reviews/${r.id}/visibility`,null,{params:{hidden:!r.hidden}});r.hidden=!r.hidden;ElMessage.success(r.hidden?'评价已隐藏':'评价已恢复')}onMounted(load)</script>
<template><div class="panel"><div class="toolbar"><h2>评价管理</h2><div><el-input-number v-model="productId" placeholder="商品ID"/><el-select v-model="rating" style="width:120px" @change="search"><el-option label="全部星级" :value="0"/><el-option v-for="n in 5" :key="n" :label="`${n} 星`" :value="n"/></el-select><el-button type="primary" @click="search">查询</el-button></div></div><el-table :data="rows"><el-table-column prop="productId" label="商品ID"/><el-table-column prop="userId" label="用户ID"/><el-table-column label="评分"><template #default="s"><el-rate :model-value="s.row.rating" disabled/></template></el-table-column><el-table-column prop="content" label="评价内容" min-width="260"/><el-table-column prop="appendCount" label="追评次数"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.hidden?'danger':'success'">{{s.row.hidden?'已隐藏':'展示中'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link :type="s.row.hidden?'success':'danger'" @click="visibility(s.row)">{{s.row.hidden?'恢复':'隐藏'}}</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无评价"/><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next, jumper" style="margin-top:18px;justify-content:flex-end" @current-change="load" @size-change="search"/></div></template>
